+// emptyRef is the shared handle of the signature with no parameters and no rest parameter.
+const emptyRef model.FunctionSignatureRef = 1
+
 func NewStore() Store {
 	return Store{
+		signatures: []model.UntypedFunctionSignature{model.NewUntypedFunctionSignature(nil, false)},
 		associated: make(map[model.SymbolRef]model.FunctionSignatureRef),
