 	}
@@ -58,6 +62,23 @@ func (s *Store) Associate(sym model.SymbolRef, ref model.FunctionSignatureRef) b
 	return true
 }

+// AssociateEmpty associates every symbol in syms with the shared signature that has no parameters and no rest
+// parameter, under a single lock acquisition. It returns false if any symbol is already associated with a different
+// signature.
+func (s *Store) AssociateEmpty(syms []model.SymbolRef) bool {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	ok := true
+	for _, sym := range syms {
+		if existing, found := s.associated[sym]; found {
+			ok = ok && existing == emptyRef
+			continue
+		}
+		s.associated[sym] = emptyRef
+	}
+	return ok
+}
+
 func (s *Store) Ref(sym model.SymbolRef) (model.FunctionSignatureRef, bool) {
